/// <summary> /// Get Sales Invoice Indicator /// Do modify the METInvoiceIndicator in the below query in case of any modifications to enum /// </summary> /// <returns>Indicator info</returns> private static str getSalesInvoiceIndicator() { str inventTransId = SysComputedColumn::returnField(tableStr(SalesOrderConfirmationLineEntity), tableStr(SalesLine), fieldStr(SalesLine, InventTransId)); str salesLineInvIndicator = strFmt(@"SELECT LEFT( STUFF( ( SELECT DISTINCT ',' + IndicatorValue FROM ( SELECT EV.NAME AS IndicatorValue FROM METSALESINVOICEINDICATORVIEW M JOIN ENUMIDTABLE EI ON EI.NAME = 'METInvoiceIndicator' JOIN ENUMVALUETABLE EV ON EV.ENUMID = EI.ID AND EV.ENUMVALUE = M.CimponentInvoiceIndicator WHERE M.INVENTTRANSID = %1 AND EV.ENUMVALUE <> 0
UNION
SELECT MSL.Indicators AS IndicatorValue FROM SALESLINE SL JOIN METSALESLINE MSL ON SL.RECID = MSL.SALESLINE WHERE SL.INVENTTRANSID = %1 AND ISNULL(MSL.Indicators, '') <> '' ) X FOR XML PATH(''), TYPE ).value('.', 'NVARCHAR(MAX)') , 1, 1, '') , 20)", inventTransId);
return salesLineInvIndicator;
}
